import{_ as r,l as o,o as e,c as n,v as l,p as s,x as t,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"掩模厂流程","description":"","frontmatter":{"title":"掩模厂流程","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-shop-flow.md","filePath":"litho/mask-shop-flow.md","lastUpdated":1789023840000}'),c={name:"litho/mask-shop-flow.md"};function E(m,a,A,b,_,k){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="掩模厂流程" tabindex="-1">掩模厂流程 <a class="header-anchor" href="#掩模厂流程" aria-label="Permalink to &quot;掩模厂流程&quot;">​</a></h1><div class="epigraph"><p>空白版进厂，电子束写出图形，再刻、检、贴膜出厂。这是掩模厂的状态机，不是把胶和镜头再国产化一遍。</p><footer>—— 对照 SEMI 掩模制造流程的公开分段：blank、write、inspect，以及 pellicle 出货</footer></div><p><a href="/litho/china-litho-supply-chain">上一课</a>把扫描仪自主拆成胶、光源、镜头和许可档位。缺口是掩模这条平行工业：晶圆厂下单的是一张合格的版，不是国产替代百分比。本课按空白–写入–检验走一遍，不重写 JSR 或蔡司。胶供应商名单留给[下一课](/litho/resist-vendors）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/litho-process-flow">光刻流程</a>把掩模当成 4× 物面。晶圆厂不生产这张版。掩模厂从空白（石英 + 铬 / MoSi，或 EUV 的 Mo/Si 多层 + 吸收体）开始，用电子束（VSB 或多束）写入抗蚀剂，显影后刻吸收体，再检验、修缺陷、贴 pellicle。任一站的缺陷都会在晶圆上变成重复打印。</p><p>国产替代课容易把「版也能做」写成整机故事的附录。本课只问流程站：谁提供 blank、谁写、谁检。站与站的供应商可以和扫描仪完全不同，许可税号也不同。</p><h3 id="写入不是光学曝光" tabindex="-1">写入不是光学曝光 <a class="header-anchor" href="#写入不是光学曝光" aria-label="Permalink to &quot;写入不是光学曝光&quot;">​</a></h3><p>掩模上的图形尺度是晶圆的四倍，但仍要纳米级 CD 和套准。写的是电子束抗蚀剂，不是 ArF 胶。多束机把时间从图形复杂度里解开，见<a href="/litho/multibeam-mask-writer">多束写掩模</a>；本课不重复炮数公式，只把它放进流程位置：write 在 blank 之后、etch 之前。</p><p><span class="marginnote">EUV 空白的多层缺陷不能靠后面刻吸收体消掉。blank 检验是独立站，不是光学版的 STARlight 换个名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开分段可以写成：blank 资格 → 涂胶 → e-beam 写入 → 显影 → 吸收体刻蚀 → CD / 套准计量 → 缺陷检验（光学或电子）→ 修理 → pellicle → 出货计量（含 AIMS 一类空中像确认，按层要求）。SEMI 相关标准给的是接口与保证项，不是某一家的内部食谱。</p><p>DUV 透射版与 EUV 反射版在 blank 和检验分叉，写入原理同类。逻辑曲线 ILT 把 write 和检验的数据量抬高，流程站不变，瓶颈从「铬好不好刻」变成「数据能不能写完、检完」。</p>',12)),(e(),s(d,null,{default:t(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BL%5B%22%E7%A9%BA%E7%99%BD%20blank%22%5D%20--%3E%20W%5B%22%E7%94%B5%E5%AD%90%E6%9D%9F%E5%86%99%E5%85%A5%22%5D%0A%20%20W%20--%3E%20ET%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%E5%88%BB%E8%9A%80%22%5D%0A%20%20ET%20--%3E%20INSP%5B%22%E7%BC%BA%E9%99%B7%20%2F%20CD%20%E6%A3%80%E9%AA%8C%22%5D%0A%20%20INSP%20--%3E%20PEL%5B%22pellicle%20%2F%20%E5%87%BA%E8%B4%A7%22%5D%0A%20%20BL%20--%3E%20BIN%5B%22EUV%20%E5%A4%9A%E5%B1%82%E7%BC%BA%E9%99%B7%E5%8F%A6%E6%A3%80%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="不要用替代率描述掩模厂" tabindex="-1">不要用替代率描述掩模厂 <a class="header-anchor" href="#不要用替代率描述掩模厂" aria-label="Permalink to &quot;不要用替代率描述掩模厂&quot;">​</a></h3><p>blank 来自 HOYA、AGC 一类公开供应商；写入工具来自 NuFlare、IMS 等；检验大量来自 KLA、Lasertec。国内掩模厂可以在成熟 DUV 上跑通同一条状态机，先进 EUV blank 与检验仍按公开短板读。本课不编合格名录，只禁止把「会写铬版」说成「EUV 掩模链已闭环」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>掩模误差因子把 blank CD 和写入误差放大到晶圆。检验的是掩模缺陷会不会在成像阈值下打印，不是晶圆随机缺孔。修理（补镀或挖）改变局部透过率，可能引入新的相位/CD 问题，所以先进层越来越靠「写对 + 检到」而不是靠修。pellicle 把颗粒焦外，改变的是使用期缺陷，不改变 write 站已经写下的图形。</p><p>计算光刻把 OPC 数据交给 write；掩模厂不负责把错误的 OPC 变成正确的晶圆，只负责把给定数据写成合格版。闭环在晶圆厂热区 SEM，不在掩模厂良率口号。曲线掩模把 MRC 从边间距改成曲率与颈宽，检验算法跟着改语言，流程站仍是 blank–write–inspect，只是数据体积和检时上涨。</p><p><span class="marginnote">掩模厂周期以天计，晶圆曝光以秒计。ILT 曲线化首先打的是这一段周期，不是扫描机 wph。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要重讲出口管制清单上的胶与镜头。不要发明国产掩模机的写速度。本课不是中国供应链第二集。下一课才回到抗蚀剂厂商——那是晶圆上的胶，不是掩模电子束胶，名字相近、工厂不同。</p><p><span class="marginnote">出处：SEMI 掩模制造流程的公开分段；掩模 blank / 写入 / 检验的产业公开分工。不把未认证的 EUV 空白写成量产。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩模厂状态机：空白 → 写入 → 刻蚀 → 检验 → pellicle。</li><li>与扫描仪胶/光源/镜头供应链平行，不是国产替代重讲。</li><li>EUV blank 缺陷与 DUV 铬版检验不是同一站。</li><li>晶圆胶供应商下一课，勿与电子束胶混厂。</li><li>出处：SEMI 掩模流程；公开 blank / writer / inspection 分工。</li></ul>',11))])}const f=r(c,[["render",E]]);export{u as __pageData,f as default};
